100	export type StorageUsage = {
101	  node: string;
102	  storage: string;
103	  total: number;
104	  used: number;
105	  avail: number;
106	  ratio: number;
107	  reachable: boolean;
108	};
109	
110	/** Per-node, per-storage disk usage (bytes). Unreachable storages are marked. */
111	export async function nodeStorageUsage(): Promise<StorageUsage[]> {
112	  const targets = await nodeTargets();
113	  const out: StorageUsage[] = [];
114	  for (const t of targets) {
115	    for (const storage of t.storages) {
116	      try {
117	        const st = await t.get(`/nodes/${t.pveNode}/storage/${storage}/status`);
118	        const total = Number(st?.total ?? 0);
119	        const used = Number(st?.used ?? 0);
120	        const avail = Number(st?.avail ?? Math.max(0, total - used));
121	        out.push({
122	          node: t.label,
123	          storage,
124	          total,
125	          used,
126	          avail,
127	          ratio: total > 0 ? used / total : 0,
128	          reachable: true,
129	        });
130	      } catch {
131	        out.push({ node: t.label, storage, total: 0, used: 0, avail: 0, ratio: 0, reachable: false });
132	      }
133	    }
134	  }
135	  return out;
136	}
137	
138	export type NodeRam = {
139	  node: string;
140	  total: number;
141	  used: number;
142	  ratio: number;
143	  cpu: number;
144	  reachable: boolean;
145	};
146	
147	/** Per-node RAM + CPU load from the node status endpoint. */
148	export async function nodeRamUsage(): Promise<NodeRam[]> {
149	  const targets = await nodeTargets();
150	  return Promise.all(
151	    targets.map(async (t) => {
152	      try {
153	        const s = await t.get(`/nodes/${t.pveNode}/status`);
154	        const total = Number(s?.memory?.total ?? 0);
155	        const used = Number(s?.memory?.used ?? 0);
156	        return {
157	          node: t.label,
158	          total,
159	          used,
160	          ratio: total > 0 ? used / total : 0,
161	          cpu: Number(s?.cpu ?? 0),
162	          reachable: true,
163	        };
164	      } catch {
165	        return { node: t.label, total: 0, used: 0, ratio: 0, cpu: 0, reachable: false };
166	      }
167	    })
168	  );
169	}
