1	import { db } from "../lib/db";
2	import { SANDBOX } from "../lib/sandbox";
3	import { pve, node as defaultNode, pveFor, getGuestDiskUsage } from "../lib/proxmox";
4	import { effectiveDiskGB } from "../lib/extra-disk";
5	import {
6	  BW_PERIOD_MS,
7	  creditFromCounters,
8	  integrateRrdBytes,
9	  readBwMeterHealth,
10	  recordBwSweep,
11	  type BwSample,
12	} from "../lib/bandwidth";
13	import {
14	  nodeStorageUsage,
15	  nodeRamUsage,
16	  backupSummary,
17	  stuckJobs,
18	  workerHealth,
19	  fmtAge,
20	  DISK_WARN_RATIO,
21	  RAM_WARN_RATIO,
22	  BACKUP_STALE_MS,
23	  QUEUE_BACKLOG_ALERT,
24	  STUCK_JOB_MS,
25	} from "../lib/monitoring";
26	
27	/**
28	 * Monitoring sweep — run periodically from the worker loop. Read-only checks
29	 * that raise dashboard notifications for all ADMINs when a threshold trips.
30	 *
31	 * Notifications are de-duplicated by title within a rolling window so a
32	 * persistent condition (e.g. a node stuck at 90% disk) alerts once every few
33	 * hours rather than every sweep.
34	 */
35	
36	const DEDUPE_HOURS = Number(process.env.NXEON_ALERT_DEDUPE_HOURS ?? 3);
37	
38	/**
39	 * Fan a single alert out to every ADMIN, unless an identically-titled alert
40	 * already went out within the dedupe window.
41	 */
42	export async function notifyAdmins(
43	  title: string,
44	  body: string,
45	  href = "/admin/monitoring"
46	): Promise<void> {
47	  const since = new Date(Date.now() - DEDUPE_HOURS * 60 * 60_000);
48	  const recent = await db.notification.findFirst({
49	    where: { title, createdAt: { gt: since } },
50	    select: { id: true },
51	  });
52	  if (recent) return;
53	
54	  const admins = await db.user.findMany({ where: { role: "ADMIN" }, select: { id: true } });
55	  if (admins.length === 0) return;
56	
57	  await db.notification.createMany({
58	    data: admins.map((a) => ({ userId: a.id, title, body, href })),
59	  });
60	}
61	
62	// Keep in-guest disk samples for ~5 weeks so the 30-day chart window always has
63	// history without letting the table grow unbounded.
64	const DISK_SAMPLE_RETENTION_DAYS = 35;
65	const GB = 1024 ** 3;
66	
67	/**
68	 * Sample real in-guest disk usage for every RUNNING VM via the QEMU guest agent
69	 * and persist a point into ServerDiskSample. Runs on the monitor cadence.
70	 *
71	 * Best-effort throughout: a missing/not-ready guest agent yields null and is
72	 * simply skipped — it never errors the sweep. In SANDBOX getGuestDiskUsage
73	 * returns a synthetic value, so staging still builds a realistic history.
74	 * Also prunes samples older than the retention window each pass.
75	 */
76	export async function sampleServerDisks(): Promise<void> {
77	  // Retention prune first (cheap, and keeps the table bounded even if sampling
78	  // below throws for every server).
79	  try {
80	    const cutoff = new Date(Date.now() - DISK_SAMPLE_RETENTION_DAYS * 24 * 60 * 60_000);
81	    await db.serverDiskSample.deleteMany({ where: { ts: { lt: cutoff } } });
82	  } catch (e) {
83	    console.error("[monitor] disk-sample prune error", e);
84	  }
85	
86	  let servers: Array<{ id: string; vmid: number | null; node: any; extraDiskGB: number; plan: { diskGB: number } }>;
87	  try {
88	    servers = await db.server.findMany({
89	      where: { status: "RUNNING", vmid: { not: null } },
90	      select: {
91	        id: true,
92	        vmid: true,
93	        extraDiskGB: true,
94	        plan: { select: { diskGB: true } },
95	        node: {
96	          select: { pveNode: true, apiUrl: true, tokenId: true, tokenSecret: true },
97	        },
98	      },
99	    });
100	  } catch (e) {
101	    console.error("[monitor] disk-sample: list servers error", e);
102	    return;
103	  }
104	
105	  for (const s of servers) {
106	    if (s.vmid == null) continue;
107	    try {
108	      const client = s.node
109	        ? pveFor({
110	            apiUrl: s.node.apiUrl,
111	            pveNode: s.node.pveNode,
112	            tokenId: s.node.tokenId,
113	            tokenSecret: s.node.tokenSecret,
114	          })
115	        : pve;
116	      const pnode = s.node?.pveNode ?? defaultNode;
117	      const usage = await getGuestDiskUsage(client, pnode, s.vmid, effectiveDiskGB(s.plan.diskGB, s.extraDiskGB) * GB);
118	      if (!usage) continue; // agent not ready — skip, no error
119	      await db.serverDiskSample.create({
120	        data: {
121	          serverId: s.id,
122	          usedBytes: BigInt(Math.max(0, Math.round(usage.usedBytes))),
123	          totalBytes: BigInt(Math.max(0, Math.round(usage.totalBytes))),
124	        },
125	      });
126	    } catch (e) {
127	      console.error(`[monitor] disk-sample error for server ${s.id}`, e);
128	    }
129	  }
130	}
131	
132	// ---------------------------------------------------------------------------
133	// Bandwidth metering sweep
134	// ---------------------------------------------------------------------------
135	
136	/**
137	 * Last counter sample per `serverId:vmid`, in worker memory.
138	 *
139	 * Deliberately not persisted: prisma/schema.prisma has no column for a raw
140	 * per-VM counter, and the two obvious substitutes are worse than a cold start —
141	 * the `Setting` KV is handed wholesale to the admin settings page (it would ship
142	 * a blob of every server's counters to the browser), and reusing
143	 * `abuseBwMark` would break the abuse window it exists for. A worker restart
144	 * therefore loses the baseline; `backfillGap` recovers the interval from RRD so
145	 * the restart costs at most the newest (still-filling) RRD bucket instead of a
146	 * whole sweep interval.
147	 *
148	 * Keyed by vmid as well as serverId so a reinstall or migration onto a different
149	 * vmid can never be compared against the old VM's counters.
150	 */
151	const bwBaselines = new Map<string, BwSample>();
152	
153	/**
154	 * Where the last sweep stopped. The sweep is time-bounded, so on a large fleet it
155	 * may not reach every server; resuming from the cursor rather than always
156	 * restarting at the first row is what stops the tail of the list from being
157	 * silently never metered — a server whose usage always reads 0 because nobody
158	 * ever looked at it is precisely the failure this whole change exists to fix.
159	 */
160	let bwCursor = 0;
161	
162	/**
163	 * Sampling runs INLINE in the worker's strictly serial job loop: every second
164	 * spent here is a second no customer job runs, so the sweep is hard-bounded.
165	 * A Proxmox node that hangs must cost one timeout, not the queue.
166	 */
167	const BW_CALL_TIMEOUT_MS = 8_000;
168	const BW_SWEEP_BUDGET_MS = 45_000;
169	/** RRD back-fill is ~10x the payload of a status read, so cap it per sweep. */
170	const BW_MAX_BACKFILLS_PER_SWEEP = 50;
171	/** Below this a gap is not worth an extra API call. */
172	const BW_BACKFILL_MIN_GAP_MS = 2 * 60_000;
173	/** `timeframe=hour` holds 60 x 60s buckets; beyond that the gap is unrecoverable. */
174	const BW_RRD_WINDOW_MS = 60 * 60_000;
175	
176	/**
177	 * Bound one Proxmox call. Note this abandons the promise rather than cancelling
178	 * the request (lib/proxmox takes no AbortSignal) — the point is that the sweep
179	 * moves on, not that the socket closes.
180	 */
181	function withTimeout<T>(p: Promise<T>, ms: number, what: string): Promise<T> {
182	  return new Promise<T>((resolve, reject) => {
183	    const timer = setTimeout(
184	      () => reject(new Error(`proxmox call timed out after ${ms}ms: ${what}`)),
185	      ms
186	    );
187	    p.then(
188	      (v) => {
189	        clearTimeout(timer);
190	        resolve(v);
191	      },
192	      (e) => {
193	        clearTimeout(timer);
194	        reject(e);
195	      }
196	    );
197	  });
198	}
