200	type BwClient = { get: (path: string, params?: Record<string, any>) => Promise<any> };
201	
202	/**
203	 * Meter every RUNNING VM's network counters onto its Server row.
204	 *
205	 * Writes `bwInBytes` / `bwOutBytes` (cumulative for the current metering period)
206	 * and `bwWindowStart` (the period marker). Nothing wrote these before, which is
207	 * why the customer's bandwidth panel read a permanent zero and worker/abuse.ts
208	 * could never fire — see lib/bandwidth.ts for the full history.
209	 *
210	 * READ-ONLY against Proxmox: `status/current` and `rrddata`, never a mutation.
211	 * Best-effort per server — one unreachable node must not cost the whole sweep.
212	 */
213	export async function sampleServerBandwidth(): Promise<void> {
214	  if (SANDBOX) return; // no real VMs, therefore no real traffic to meter
215	
216	  const sweepStartMs = Date.now();
217	  let health;
218	  try {
219	    health = await readBwMeterHealth(sweepStartMs);
220	  } catch (e) {
221	    console.error("[bandwidth] could not read meter markers", e);
222	    return;
223	  }
224	  // End of the previous sweep — where a cold-start back-fill starts counting.
225	  // Only the cold path uses it; the warm path uses each baseline's own
226	  // timestamp, so a sweep cadence that drifts (or a sweep that gets skipped
227	  // entirely) stays correct without assuming a fixed interval.
228	  const priorSweepMs = health.lastAt?.getTime() ?? null;
229	
230	  let servers: Array<{
231	    id: string;
232	    hostname: string;
233	    vmid: number | null;
234	    bwWindowStart: Date;
235	    node: {
236	      pveNode: string;
237	      apiUrl: string;
238	      tokenId: string;
239	      tokenSecret: string;
240	    } | null;
241	  }>;
242	  try {
243	    servers = await db.server.findMany({
244	      where: { status: "RUNNING", vmid: { not: null } },
245	      select: {
246	        id: true,
247	        hostname: true,
248	        vmid: true,
249	        bwWindowStart: true,
250	        node: { select: { pveNode: true, apiUrl: true, tokenId: true, tokenSecret: true } },
251	      },
252	      orderBy: { id: "asc" }, // stable order, so the cursor below means something
253	    });
254	  } catch (e) {
255	    console.error("[bandwidth] list servers error", e);
256	    return;
257	  }
258	
259	  // On the very first sweep there is no stored start yet; treat now as the start
260	  // so window normalisation below has a truthful lower bound to work with.
261	  const startedAtMs = health.startedAt?.getTime() ?? sweepStartMs;
262	
263	  let sampled = 0;
264	  let backfills = 0;
265	  let backfilled = false;
266	  let gapDetected = false;
267	
268	  // Every RUNNING VM's key, whether or not this sweep reaches it, so the prune at
269	  // the end can't throw away a baseline we still want.
270	  const liveKeys = new Set(
271	    servers.filter((s) => s.vmid != null).map((s) => `${s.id}:${s.vmid}`)
272	  );
273	
274	  const total = servers.length;
275	  const startIdx = total > 0 ? bwCursor % total : 0;
276	  let visited = 0;
277	
278	  for (let i = 0; i < total; i++) {
279	    const s = servers[(startIdx + i) % total];
280	    if (s.vmid == null) {
281	      visited++;
282	      continue;
283	    }
284	    const key = `${s.id}:${s.vmid}`;
285	
286	    if (Date.now() - sweepStartMs > BW_SWEEP_BUDGET_MS) {
287	      // Out of budget. Baselines are kept, so the servers we skipped are simply
288	      // metered over a longer interval next sweep — no traffic is lost — and the
289	      // cursor makes the next sweep start where this one stopped.
290	      console.warn(
291	        `[bandwidth] sweep budget exhausted after ${visited} of ${total} servers; ` +
292	          `resuming from there next sweep`
293	      );
294	      break;
295	    }
296	    visited++;
297	
298	    const client: BwClient = s.node
299	      ? pveFor({
300	          apiUrl: s.node.apiUrl,
301	          pveNode: s.node.pveNode,
302	          tokenId: s.node.tokenId,
303	          tokenSecret: s.node.tokenSecret,
304	        })
305	      : pve;
306	    const pnode = s.node?.pveNode ?? defaultNode;
307	
308	    try {
309	      const cur = await withTimeout(
310	        client.get(`/nodes/${pnode}/qemu/${s.vmid}/status/current`),
311	        BW_CALL_TIMEOUT_MS,
312	        `status/current vm ${s.vmid}`
313	      );
314	      // Our DB says RUNNING but Proxmox is authoritative. A stopped VM reports
315	      // netin/netout 0, and treating that as a counter rollback would be noise.
316	      if (String(cur?.status ?? "") !== "running") {
317	        bwBaselines.delete(key);
318	        continue;
319	      }
320	      const netin = Number(cur?.netin);
321	      const netout = Number(cur?.netout);
322	      if (!Number.isFinite(netin) || !Number.isFinite(netout)) {
323	        // Node too old / unexpected payload: no counters, nothing to meter.
324	        continue;
325	      }
326	      const sample: BwSample = {
327	        netin,
328	        netout,
329	        uptimeSec: Number(cur?.uptime) || 0,
330	        pid: Number.isFinite(Number(cur?.pid)) ? Number(cur.pid) : null,
331	        atMs: Date.now(),
332	      };
333	
334	      const prev = bwBaselines.get(key);
335	      bwBaselines.set(key, sample);
336	      sampled++;
337	
338	      let inBytes = 0;
339	      let outBytes = 0;
340	
341	      if (prev) {
342	        const credit = creditFromCounters(prev, sample);
343	        inBytes = credit.inBytes;
344	        outBytes = credit.outBytes;
345	        if (credit.reason !== "delta") {
346	          // Logged, never silent: each of these means the customer's total is
347	          // missing traffic we could not attribute, and an operator chasing a
348	          // suspiciously low figure needs to see it.
349	          console.warn(
350	            `[bandwidth] ${s.hostname} (vm ${s.vmid}) counter ${credit.reason} — ` +
351	              `credited ${inBytes} in / ${outBytes} out (prev ${prev.netin}/${prev.netout} ` +
352	              `pid ${prev.pid} up ${prev.uptimeSec}s → now ${sample.netin}/${sample.netout} ` +
353	              `pid ${sample.pid} up ${sample.uptimeSec}s)`
354	          );
355	        }
356	      } else if (priorSweepMs !== null) {
357	        // Cold start (worker restarted, or this VM just came up). The counter
358	        // baseline is gone, so recover the interval from RRD rate data instead
359	        // of dropping it — without this, every redeploy silently erases up to a
360	        // sweep interval of every customer's usage.
361	        const gapMs = sweepStartMs - priorSweepMs;
362	        if (gapMs > BW_RRD_WINDOW_MS) {
363	          // Longer than RRD's hour window: part of this gap is unrecoverable.
364	          // Recorded so the UI can admit the period under-reports.
365	          gapDetected = true;
366	        }
367	        if (gapMs >= BW_BACKFILL_MIN_GAP_MS && backfills < BW_MAX_BACKFILLS_PER_SWEEP) {
368	          backfills++;
369	          const filled = await backfillGap(client, pnode, s.vmid, priorSweepMs, sample.atMs);
370	          if (filled) {
371	            inBytes = filled.inBytes;
372	            outBytes = filled.outBytes;
373	            backfilled = true;
374	          }
375	        }
376	      }
377	
378	      const roundedIn = Math.max(0, Math.round(inBytes));
379	      const roundedOut = Math.max(0, Math.round(outBytes));
380	
381	      // The period marker predates metering on every row created before this
382	      // sweep existed (it defaults to the row's creation date), so pull it
383	      // forward to the moment measurement actually began. Without this the UI
384	      // would claim these bytes cover months we never watched.
385	      const needsWindowFix = s.bwWindowStart.getTime() < startedAtMs;
386	      const effectiveWindowMs = Math.max(s.bwWindowStart.getTime(), startedAtMs);
387	      const roll = sample.atMs - effectiveWindowMs >= BW_PERIOD_MS;
388	
389	      if (roundedIn === 0 && roundedOut === 0 && !roll && !needsWindowFix) {
390	        continue; // nothing to record — skip the write entirely
391	      }
392	
393	      if (roll) {
394	        // New period: these bytes belong to the period starting now.
395	        await db.server.update({
396	          where: { id: s.id },
397	          data: {
398	            bwInBytes: BigInt(roundedIn),
399	            bwOutBytes: BigInt(roundedOut),
400	            bwWindowStart: new Date(sample.atMs),
401	          },
402	        });
403	      } else {
404	        await db.server.update({
405	          where: { id: s.id },
406	          data: {
407	            bwInBytes: { increment: BigInt(roundedIn) },
408	            bwOutBytes: { increment: BigInt(roundedOut) },
409	            ...(needsWindowFix ? { bwWindowStart: new Date(startedAtMs) } : {}),
410	          },
411	        });
412	      }
413	    } catch (e) {
414	      console.error(`[bandwidth] sample error for ${s.hostname} (vm ${s.vmid})`, e);
415	    }
416	  }
417	
418	  bwCursor = total > 0 ? (startIdx + visited) % total : 0;
419	
420	  // Drop baselines for VMs no longer in the RUNNING set (deleted, stopped,
421	  // suspended, reinstalled onto a new vmid) so the map stays bounded. Servers
422	  // skipped by the time budget ARE in liveKeys, so their baselines survive.
423	  for (const key of [...bwBaselines.keys()]) {
424	    if (!liveKeys.has(key)) bwBaselines.delete(key);
425	  }
426	
427	  try {
428	    await recordBwSweep({
429	      sweepEndMs: Date.now(),
430	      sampled,
431	      candidates: total,
432	      gapDetected,
433	      backfilled,
434	      hadStartedAt: health.startedAt !== null,
435	    });
436	  } catch (e) {
437	    console.error("[bandwidth] could not record sweep markers", e);
438	  }
439	}
