441	/**
442	 * Recover a metering gap for one VM from RRD rate data.
443	 *
444	 * Returns null (rather than 0) when RRD had nothing usable, so the caller does
445	 * not treat "no data" as "no traffic". Bounded by the same per-call timeout as
446	 * the counter read.
447	 */
448	async function backfillGap(
449	  client: BwClient,
450	  pnode: string,
451	  vmid: number,
452	  fromMs: number,
453	  toMs: number
454	): Promise<{ inBytes: number; outBytes: number } | null> {
455	  try {
456	    const rows = await withTimeout(
457	      client.get(`/nodes/${pnode}/qemu/${vmid}/rrddata`, { timeframe: "hour", cf: "AVERAGE" }),
458	      BW_CALL_TIMEOUT_MS,
459	      `rrddata vm ${vmid}`
460	    );
461	    const filled = integrateRrdBytes(
462	      Array.isArray(rows) ? rows : [],
463	      Math.floor(fromMs / 1000),
464	      Math.floor(toMs / 1000)
465	    );
466	    if (!filled) return null;
467	    return { inBytes: filled.inBytes, outBytes: filled.outBytes };
468	  } catch (e) {
469	    console.error(`[bandwidth] rrd back-fill failed for vm ${vmid}`, e);
470	    return null;
471	  }
472	}
