474	export async function monitorSweep(): Promise<void> {
475	  if (SANDBOX) return; // no real nodes/Proxmox to monitor in the sandbox
476	
477	  // 0. Bandwidth metering. Runs FIRST and inside monitorSweep on purpose:
478	  //    worker/index.ts calls monitorSweep() and then abuseSweep() in the same
479	  //    block, so metering this way guarantees the abuse detector reads counters
480	  //    from this sweep rather than the previous one — and needs no change to the
481	  //    worker loop, which other work owns.
482	  try {
483	    await sampleServerBandwidth();
484	  } catch (e) {
485	    console.error("[bandwidth] sweep error", e);
486	  }
487	  // 1. Node disk usage > threshold
488	  try {
489	    const storage = await nodeStorageUsage();
490	    for (const s of storage) {
491	      if (s.reachable && s.total > 0 && s.ratio > DISK_WARN_RATIO) {
492	        const pct = Math.round(s.ratio * 100);
493	        await notifyAdmins(
494	          `Disk capacity warning — ${s.node}/${s.storage} at ${pct}%`,
495	          `Storage "${s.storage}" on node ${s.node} is ${pct}% full ` +
496	            `(${(s.avail / 1024 ** 3).toFixed(0)} GB free). Free space or add capacity to keep provisioning healthy.`
497	        );
498	      }
499	    }
500	  } catch (e) {
501	    console.error("[monitor] disk check error", e);
502	  }
503	
504	  // 2. Node RAM pressure > threshold
505	  try {
506	    const ram = await nodeRamUsage();
507	    for (const r of ram) {
508	      if (r.reachable && r.total > 0 && r.ratio > RAM_WARN_RATIO) {
509	        const pct = Math.round(r.ratio * 100);
510	        await notifyAdmins(
511	          `Memory pressure — ${r.node} at ${pct}%`,
512	          `Node ${r.node} RAM is ${pct}% used. New deploys may be refused until usage drops.`
513	        );
514	      }
515	    }
516	  } catch (e) {
517	    console.error("[monitor] ram check error", e);
518	  }
519	
520	  // 3. Stuck jobs (RUNNING beyond the stuck threshold)
521	  try {
522	    const stuck = await stuckJobs();
523	    if (stuck.length > 0) {
524	      const mins = Math.round(STUCK_JOB_MS / 60_000);
525	      const lines = stuck
526	        .slice(0, 8)
527	        .map(
528	          (j) =>
529	            `• ${j.type}${j.hostname ? ` (${j.hostname})` : ""} — running ${fmtAge(
530	              Date.now() - j.updatedAt.getTime()
531	            )}`
532	        )
533	        .join("\n");
534	      await notifyAdmins(
535	        `Stuck jobs — ${stuck.length} running > ${mins}m`,
536	        `The worker has job(s) stuck in RUNNING:\n${lines}`
537	      );
538	    }
539	  } catch (e) {
540	    console.error("[monitor] stuck-job check error", e);
541	  }
542	
543	  // 4. Worker liveness + pending-job backlog
544	  try {
545	    const wh = await workerHealth();
546	    if (wh.status === "down") {
547	      await notifyAdmins(
548	        "Worker appears stopped",
549	        wh.detail + ". Check the provisioning worker process."
550	      );
551	    }
552	    if (wh.queuedBacklog >= QUEUE_BACKLOG_ALERT) {
553	      await notifyAdmins(
554	        `Job backlog building — ${wh.queuedBacklog} queued`,
555	        `${wh.queuedBacklog} jobs are waiting in the queue. The worker may be overloaded or slow.`
556	      );
557	    }
558	  } catch (e) {
559	    console.error("[monitor] worker check error", e);
560	  }
561	
562	  // 5. Backup freshness (best-effort; skipped if backup storage isn't listable)
563	  try {
564	    const bk = await backupSummary();
565	    if (bk.reachable && bk.count > 0 && bk.newestCtime !== null) {
566	      const ageMs = Date.now() - bk.newestCtime * 1000;
567	      if (ageMs > BACKUP_STALE_MS) {
568	        await notifyAdmins(
569	          `Backups look stale — newest is ${fmtAge(ageMs)} old`,
570	          `The most recent backup on disk is ${fmtAge(ageMs)} old. Verify the backup schedule is running.`
571	        );
572	      }
573	    }
574	  } catch (e) {
575	    console.error("[monitor] backup check error", e);
576	  }
577	}
