"use server";

import { db } from "./db";
import { requireArea } from "./rbac";
import { revalidatePath } from "next/cache";
import { HEALTH_COMPONENTS, type IncidentSeverity } from "./monitoring";

/**
 * Manual incident management for the status page. Fleet-area staff post an
 * incident (planned maintenance, a customer-visible degradation the auto-monitor
 * can't infer) and resolve it when it's over.
 *
 * "use server" means every export here is a public HTTP endpoint, so each one
 * re-checks `requireArea("fleet")` INSIDE the function — the admin page gate is
 * not enough on its own.
 *
 * Auto-opened incidents (auto=true) are owned by the sampleHealth() state
 * machine; these actions only touch operator-posted ones (auto=false) so a
 * manual resolve can never fight the auto-resolver over the same row.
 */

const SEVERITIES: IncidentSeverity[] = ["degraded", "down", "maintenance"];

type Result = { ok?: boolean; id?: string; error?: string };

export async function postIncident(input: {
  title: string;
  body?: string;
  severity: string;
  component?: string | null;
}): Promise<Result> {
  const admin = await requireArea("fleet");

  const title = (input.title ?? "").trim();
  if (!title) return { error: "A title is required." };
  if (title.length > 140) return { error: "Title is too long (max 140 characters)." };

  const severity = SEVERITIES.includes(input.severity as IncidentSeverity)
    ? (input.severity as IncidentSeverity)
    : "degraded";

  // Empty string ⇒ platform-wide; otherwise it must be one of the known components.
  const rawComponent = (input.component ?? "").trim();
  let component: string | null = null;
  if (rawComponent) {
    if (!(HEALTH_COMPONENTS as readonly string[]).includes(rawComponent)) {
      return { error: "Unknown component." };
    }
    component = rawComponent;
  }

  const body = (input.body ?? "").trim().slice(0, 2000);

  const incident = await db.statusIncident.create({
    data: { title, body, severity, component, auto: false },
  });

  await db.auditLog.create({
    data: { userId: admin.id, action: "status.incident.post", detail: `${severity} — ${title}` },
  });

  revalidatePath("/admin/monitoring");
  revalidatePath("/status");
  return { ok: true, id: incident.id };
}

export async function resolveIncident(id: string): Promise<Result> {
  const admin = await requireArea("fleet");

  const incident = await db.statusIncident.findUnique({ where: { id } });
  if (!incident) return { error: "Incident not found." };
  if (incident.resolvedAt) return { error: "Incident is already resolved." };

  await db.statusIncident.update({ where: { id }, data: { resolvedAt: new Date() } });
  await db.auditLog.create({
    data: { userId: admin.id, action: "status.incident.resolve", detail: `${incident.title} (${id})` },
  });

  revalidatePath("/admin/monitoring");
  revalidatePath("/status");
  return { ok: true };
}

export async function reopenIncident(id: string): Promise<Result> {
  const admin = await requireArea("fleet");

  const incident = await db.statusIncident.findUnique({ where: { id } });
  if (!incident) return { error: "Incident not found." };
  // Only operator-posted incidents can be manually reopened; auto incidents are
  // driven purely by the sample state machine.
  if (incident.auto) return { error: "Auto-generated incidents cannot be reopened manually." };
  if (!incident.resolvedAt) return { error: "Incident is already open." };

  await db.statusIncident.update({ where: { id }, data: { resolvedAt: null } });
  await db.auditLog.create({
    data: { userId: admin.id, action: "status.incident.reopen", detail: `${incident.title} (${id})` },
  });

  revalidatePath("/admin/monitoring");
  revalidatePath("/status");
  return { ok: true };
}

"use client";

import { useEffect, useRef, useState } from "react";
import { useRouter } from "next/navigation";

/**
 * Client-side auto-refresh for the public /status page.
 *
 * The page copy promises component states refresh "roughly every 15 seconds",
 * but the page is a server component with no client polling — so until now that
 * sentence was aspirational. This calls `router.refresh()` on the interval,
 * which re-runs the (force-dynamic) server component and swaps in fresh,
 * already-sanitized markup. It fetches NO data itself, so there is no public
 * JSON surface to leak internals through — the server page stays the only place
 * health is read, and it already shows friendly names only.
 *
 * Pauses while the tab is hidden (no point polling a backgrounded page) and
 * resumes — with an immediate refresh — when it becomes visible again.
 */
export function AutoRefresh({ intervalMs = 15_000 }: { intervalMs?: number }) {
  const router = useRouter();
  const [refreshing, setRefreshing] = useState(false);
  const timer = useRef<ReturnType<typeof setInterval> | null>(null);

  useEffect(() => {
    const tick = () => {
      if (document.visibilityState !== "visible") return;
      setRefreshing(true);
      router.refresh();
      // Clear the pulse shortly after; refresh() has no completion callback.
      window.setTimeout(() => setRefreshing(false), 800);
    };

    const start = () => {
      if (timer.current) return;
      timer.current = setInterval(tick, intervalMs);
    };
    const stop = () => {
      if (timer.current) {
        clearInterval(timer.current);
        timer.current = null;
      }
    };

    const onVisibility = () => {
      if (document.visibilityState === "visible") {
        tick();
        start();
      } else {
        stop();
      }
    };

    start();
    document.addEventListener("visibilitychange", onVisibility);
    return () => {
      stop();
      document.removeEventListener("visibilitychange", onVisibility);
    };
  }, [router, intervalMs]);

  return (
    <span className="inline-flex items-center gap-1.5 text-xs text-slate-500">
      <span
        className={`h-1.5 w-1.5 rounded-full ${
          refreshing ? "bg-brand-400 animate-pulse-dot" : "bg-slate-600"
        }`}
      />
      Auto-refreshing
    </span>
  );
}

