"use client";

/**
 * The public status-history strip: one thin bar per time bucket, coloured by the
 * WORST status seen in that bucket. Buckets with no samples render neutral
 * ("no data") rather than green, so a page that has only just started collecting
 * cannot look like a flawless history it never measured.
 *
 * Purely presentational — it receives already-bucketed, already-public data from
 * the server page (numbers + a coarse status only, never a probe `detail`).
 */

type TimelineStatus = "operational" | "degraded" | "down" | null;

export type TimelineBucketView = {
  start: number;
  end: number;
  status: TimelineStatus;
  total: number;
};

const BAR_COLOR: Record<"operational" | "degraded" | "down", string> = {
  operational: "bg-emerald-400/80",
  degraded: "bg-amber-400/80",
  down: "bg-red-400/80",
};

const STATUS_WORD: Record<"operational" | "degraded" | "down", string> = {
  operational: "Operational",
  degraded: "Degraded",
  down: "Outage",
};

function tip(b: TimelineBucketView): string {
  const d = new Date(b.start).toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    timeZone: "UTC",
  });
  if (b.status === null || b.total === 0) return `${d} — no data`;
  return `${d} — ${STATUS_WORD[b.status]}`;
}

export function HealthTimeline({ buckets }: { buckets: TimelineBucketView[] }) {
  if (buckets.length === 0) {
    return <p className="text-xs text-slate-500">Collecting data…</p>;
  }
  return (
    <div className="flex items-end gap-[2px]" role="img" aria-label="Status history">
      {buckets.map((b, i) => (
        <span
          key={i}
          title={tip(b)}
          className={`h-7 flex-1 rounded-[2px] ${
            b.status && b.total > 0 ? BAR_COLOR[b.status] : "bg-white/[0.06]"
          }`}
        />
      ))}
    </div>
  );
}

"use client";

import { COMPONENT_LABELS, SEVERITY_LABEL, type HealthComponentKey } from "@/lib/status-copy";

/**
 * Public incident history. Renders open incidents first, then recently resolved
 * ones, each with its severity, affected component, and human-readable window.
 *
 * Every field here is curated, public-safe copy: titles/bodies come from the
 * operator or from the generic auto-incident wording — never from a probe's raw
 * `detail`. This component NEVER receives internal error text.
 */

type Severity = "degraded" | "down" | "maintenance";

export type IncidentItem = {
  id: string;
  component: HealthComponentKey | null;
  severity: Severity;
  title: string;
  body: string;
  startedAt: string;
  resolvedAt: string | null;
  auto: boolean;
};

const SEV_META: Record<Severity, { dot: string; text: string }> = {
  down: { dot: "bg-red-400", text: "text-red-300" },
  degraded: { dot: "bg-amber-400", text: "text-amber-300" },
  maintenance: { dot: "bg-brand-400", text: "text-brand-300" },
};

function fmt(iso: string): string {
  return new Date(iso).toLocaleString("en-US", {
    dateStyle: "medium",
    timeStyle: "short",
    timeZone: "UTC",
  });
}

function IncidentCard({ inc }: { inc: IncidentItem }) {
  const sev = SEV_META[inc.severity] ?? SEV_META.degraded;
  const compName = inc.component ? COMPONENT_LABELS[inc.component] : "Platform-wide";
  const resolved = !!inc.resolvedAt;
  return (
    <div className="px-6 py-5">
      <div className="flex items-start justify-between gap-4">
        <div className="min-w-0">
          <div className="flex items-center gap-2">
            <span className={`h-2.5 w-2.5 shrink-0 rounded-full ${sev.dot} ${resolved ? "opacity-40" : "animate-pulse-dot"}`} />
            <p className="truncate font-medium text-white">{inc.title}</p>
          </div>
          <p className="mt-1 text-sm leading-relaxed text-slate-400">{inc.body}</p>
          <p className="mt-2 text-xs text-slate-500">
            <span className={sev.text}>{SEVERITY_LABEL[inc.severity]}</span>
            {" · "}
            {compName}
            {" · "}
            Started {fmt(inc.startedAt)} UTC
            {resolved && inc.resolvedAt ? ` · Resolved ${fmt(inc.resolvedAt)} UTC` : ""}
          </p>
        </div>
        <span
          className={`shrink-0 rounded-full border px-2.5 py-0.5 text-xs font-medium ${
            resolved
              ? "border-emerald-500/30 bg-emerald-500/10 text-emerald-300"
              : "border-amber-500/30 bg-amber-500/10 text-amber-300"
          }`}
        >
          {resolved ? "Resolved" : "Active"}
        </span>
      </div>
    </div>
  );
}

export function IncidentList({ open, resolved }: { open: IncidentItem[]; resolved: IncidentItem[] }) {
  if (open.length === 0 && resolved.length === 0) {
    return (
      <div className="card">
        <p className="text-sm text-slate-400">
          No incidents reported in this window. When a component stays unhealthy across monitoring
          checks — or an operator posts one — it will appear here with a full timeline.
        </p>
      </div>
    );
  }
  return (
    <div className="space-y-6">
      {open.length > 0 && (
        <div className="card divide-y divide-white/[0.06] p-0">
          <div className="px-6 pt-5 pb-2">
            <p className="section-label">Active incidents</p>
          </div>
          {open.map((inc) => (
            <IncidentCard key={inc.id} inc={inc} />
          ))}
        </div>
      )}
      {resolved.length > 0 && (
        <div className="card divide-y divide-white/[0.06] p-0">
          <div className="px-6 pt-5 pb-2">
            <p className="section-label">Past incidents</p>
          </div>
          {resolved.map((inc) => (
            <IncidentCard key={inc.id} inc={inc} />
          ))}
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { postIncident, resolveIncident, reopenIncident } from "@/lib/actions-status";
import { COMPONENT_LABELS, SEVERITY_LABEL, type HealthComponentKey } from "@/lib/status-copy";

/**
 * Fleet-area incident console. Posts a manual StatusIncident (planned
 * maintenance, a customer-visible issue the auto-monitor can't infer) and
 * resolves/reopens operator-posted ones. Auto-generated incidents show here too
 * but are read-only — they are driven by the sampleHealth() state machine.
 *
 * Authorisation is enforced server-side inside each action (requireArea("fleet")),
 * not by this component; the UI gate is convenience only.
 */

type Severity = "degraded" | "down" | "maintenance";

export type AdminIncident = {
  id: string;
  component: HealthComponentKey | null;
  severity: Severity;
  title: string;
  body: string;
  startedAt: string;
  resolvedAt: string | null;
  auto: boolean;
};

const COMPONENTS: HealthComponentKey[] = ["web", "proxmox", "worker", "db"];
const SEVERITIES: Severity[] = ["degraded", "down", "maintenance"];

function fmt(iso: string): string {
  return new Date(iso).toLocaleString("en-US", { dateStyle: "medium", timeStyle: "short", timeZone: "UTC" });
}

export function IncidentManager({ incidents }: { incidents: AdminIncident[] }) {
  const router = useRouter();
  const [pending, startTransition] = useTransition();
  const [title, setTitle] = useState("");
  const [body, setBody] = useState("");
  const [severity, setSeverity] = useState<Severity>("degraded");
  const [component, setComponent] = useState<string>("");
  const [error, setError] = useState<string | null>(null);

  function submit(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    startTransition(async () => {
      const res = await postIncident({ title, body, severity, component: component || null });
      if (res.error) {
        setError(res.error);
        return;
      }
      setTitle("");
      setBody("");
      setSeverity("degraded");
      setComponent("");
      router.refresh();
    });
  }

  function act(fn: (id: string) => Promise<{ error?: string }>, id: string) {
    setError(null);
    startTransition(async () => {
      const res = await fn(id);
      if (res.error) setError(res.error);
      else router.refresh();
    });
  }

  return (
    <div className="card p-5">
      <h2 className="font-semibold">Incidents</h2>
      <p className="mt-1 text-xs text-slate-500">
        Post a maintenance window or a customer-visible issue to the public status page. Auto-detected
        incidents are managed by the monitor and cannot be edited here.
      </p>

      <form onSubmit={submit} className="mt-4 space-y-3">
        <input
          className="input w-full"
          placeholder="Incident title (e.g. Scheduled network maintenance)"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          maxLength={140}
          required
        />
        <textarea
          className="input min-h-20 w-full"
          placeholder="Customer-facing description (optional)"
          value={body}
          onChange={(e) => setBody(e.target.value)}
          maxLength={2000}
        />
        <div className="flex flex-wrap gap-3">
          <select className="input" value={severity} onChange={(e) => setSeverity(e.target.value as Severity)}>
            {SEVERITIES.map((s) => (
              <option key={s} value={s}>
                {SEVERITY_LABEL[s]}
              </option>
            ))}
          </select>
          <select className="input" value={component} onChange={(e) => setComponent(e.target.value)}>
            <option value="">Platform-wide</option>
            {COMPONENTS.map((c) => (
              <option key={c} value={c}>
                {COMPONENT_LABELS[c]}
              </option>
            ))}
          </select>
          <button type="submit" className="btn-primary" disabled={pending || !title.trim()}>
            {pending ? "Posting…" : "Post incident"}
          </button>
        </div>
        {error && <p className="text-sm text-red-400">{error}</p>}
      </form>

      <div className="mt-6 space-y-2">
        {incidents.length === 0 && <p className="text-sm text-slate-500">No incidents on record.</p>}
        {incidents.map((inc) => {
          const resolved = !!inc.resolvedAt;
          return (
            <div
              key={inc.id}
              className="flex items-start justify-between gap-4 rounded-lg border border-white/[0.06] p-3"
            >
              <div className="min-w-0">
                <p className="truncate text-sm font-medium text-white">
                  {inc.title}
                  {inc.auto && (
                    <span className="ml-2 rounded-full border border-white/10 bg-white/[0.05] px-2 py-0.5 text-[10px] text-slate-400">
                      auto
                    </span>
                  )}
                </p>
                <p className="mt-0.5 text-xs text-slate-500">
                  {SEVERITY_LABEL[inc.severity]}
                  {" · "}
                  {inc.component ? COMPONENT_LABELS[inc.component] : "Platform-wide"}
                  {" · "}
                  {fmt(inc.startedAt)} UTC
                  {resolved && inc.resolvedAt ? ` → resolved ${fmt(inc.resolvedAt)} UTC` : ""}
                </p>
              </div>
              <div className="flex shrink-0 gap-2">
                {!resolved ? (
                  <button
                    className="btn-ghost text-xs"
                    disabled={pending}
                    onClick={() => act(resolveIncident, inc.id)}
                  >
                    Resolve
                  </button>
                ) : !inc.auto ? (
                  <button
                    className="btn-ghost text-xs"
                    disabled={pending}
                    onClick={() => act(reopenIncident, inc.id)}
                  >
                    Reopen
                  </button>
                ) : (
                  <span className="text-xs text-emerald-400">resolved</span>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

import type { Metadata } from "next";
import { MarketingHeader } from "@/components/marketing/MarketingHeader";
import { MarketingFooter } from "@/components/marketing/MarketingFooter";
import {
  getHealth,
  overallStatus,
  uptimeSummary,
  allTimelines,
  listIncidents,
  UPTIME_WINDOW_MS,
  type CompStatus,
} from "@/lib/monitoring";
import { OVERALL_TITLE } from "@/lib/status-copy";
import { AutoRefresh } from "@/components/status/AutoRefresh";
import { HealthTimeline } from "@/components/status/HealthTimeline";
import { IncidentList } from "@/components/status/IncidentList";

const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "System Status",
  description:
    "Live operational status of the Nxeon platform — web dashboard, provisioning, automation and databases.",
  alternates: { canonical: "/status" },
  openGraph: {
    type: "website",
    title: "Nxeon System Status",
    description: "Live operational status of the Nxeon platform.",
    url: `${APP_URL}/status`,
  },
};

const STATUS_META: Record<CompStatus, { label: string; dot: string; text: string; pulse?: boolean }> = {
  operational: { label: "Operational", dot: "bg-emerald-400", text: "text-emerald-400", pulse: true },
  degraded: { label: "Degraded performance", dot: "bg-amber-400", text: "text-amber-400", pulse: true },
  down: { label: "Outage", dot: "bg-red-400", text: "text-red-400", pulse: true },
};

// Titles come from lib/status-copy so this page and the site-wide footer cannot
// drift apart — one of them used to be a hardcoded literal that never checked.
const OVERALL_META: Record<CompStatus, { title: string; ring: string; border: string; dot: string }> = {
  operational: {
    title: OVERALL_TITLE.operational,
    ring: "bg-emerald-500/15",
    border: "border-emerald-500/20 bg-emerald-500/[0.06]",
    dot: "bg-emerald-400",
  },
  degraded: {
    title: OVERALL_TITLE.degraded,
    ring: "bg-amber-500/15",
    border: "border-amber-500/20 bg-amber-500/[0.06]",
    dot: "bg-amber-400",
  },
  down: {
    title: OVERALL_TITLE.down,
    ring: "bg-red-500/15",
    border: "border-red-500/20 bg-red-500/[0.06]",
    dot: "bg-red-400",
  },
};

// Public-facing component labels. We deliberately show friendly names and NOT
// the internal `detail` strings, which can carry operational specifics.
const COMPONENT_META: { key: "web" | "proxmox" | "worker" | "db"; name: string; description: string }[] = [
  { key: "web", name: "Web & Dashboard", description: "Marketing site, customer portal and admin console" },
  { key: "proxmox", name: "Provisioning & Compute", description: "Hypervisor, server creation, power and resize actions" },
  { key: "worker", name: "Automation & Jobs", description: "Provisioning worker, backups and scheduled tasks" },
  { key: "db", name: "Platform Database", description: "Accounts, billing and server records" },
];

const WINDOW_DAYS = Math.round(UPTIME_WINDOW_MS / (24 * 60 * 60_000));

/** Uptime % → friendly text, honestly admitting when there's no history yet. */
function uptimeLabel(pct: number | null): string {
  if (pct === null) return "Collecting data";
  // Two decimals near the top so a 99.9x SLA reads truthfully, whole % lower down.
  return pct >= 99 ? `${pct.toFixed(2)}% uptime` : `${pct.toFixed(1)}% uptime`;
}

export default async function StatusPage() {
  const [health, uptime, timelines, incidents] = await Promise.all([
    getHealth(),
    uptimeSummary(),
    allTimelines(UPTIME_WINDOW_MS, WINDOW_DAYS),
    listIncidents(),
  ]);
  const overall = overallStatus(health);
  const om = OVERALL_META[overall];

  const checkedAt = new Date(health.checkedAt).toLocaleString("en-US", {
    dateStyle: "medium",
    timeStyle: "short",
    timeZone: "UTC",
  });

  return (
    <div className="flex min-h-screen flex-col">
      <MarketingHeader />
      {/* Re-runs this (force-dynamic) server component every ~15s — no client
          data-fetch, so nothing internal is exposed. */}
      <AutoRefresh intervalMs={15_000} />
      <main className="flex-1">
        <section className="relative overflow-hidden">
          <div
            className="pointer-events-none absolute inset-x-0 top-0 h-[320px] opacity-70"
            style={{
              backgroundImage:
                "radial-gradient(ellipse 55% 50% at 50% 0%, rgba(16,185,129,0.12), transparent)",
            }}
          />
          <div className="relative mx-auto max-w-4xl px-5 pt-16 sm:px-6">
            <div className="mb-3 flex items-center justify-between">
              <p className="section-label">System Status</p>
              <AutoRefresh intervalMs={15_000} />
            </div>

            {/* Overall banner */}
            <div className={`card flex items-center gap-4 ${om.border}`}>
              <span className={`relative flex h-11 w-11 shrink-0 items-center justify-center rounded-full ${om.ring}`}>
                <span className={`h-3 w-3 rounded-full ${om.dot} animate-pulse-dot`} />
              </span>
              <div>
                <h1 className="text-xl font-bold tracking-tight text-white">{om.title}</h1>
                <p className="mt-0.5 text-sm text-slate-400">Last checked {checkedAt} UTC</p>
              </div>
            </div>
          </div>
        </section>

        {/* Components with per-component uptime + history strip */}
        <section className="mx-auto max-w-4xl px-5 py-10 sm:px-6">
          <div className="mb-3 flex items-baseline justify-between">
            <h2 className="section-label">Components</h2>
            <span className="text-xs text-slate-500">Uptime over the last {WINDOW_DAYS} days</span>
          </div>
          <div className="card divide-y divide-white/[0.06] p-0">
            {COMPONENT_META.map((c) => {
              const status = health[c.key].status;
              const meta = STATUS_META[status];
              const up = uptime[c.key];
              return (
                <div key={c.key} className="px-6 py-5">
                  <div className="flex items-center justify-between gap-4">
                    <div>
                      <p className="font-medium text-white">{c.name}</p>
                      <p className="mt-0.5 text-sm text-slate-400">{c.description}</p>
                    </div>
                    <span className={`inline-flex shrink-0 items-center gap-2 text-sm font-medium ${meta.text}`}>
                      <span className={`h-2.5 w-2.5 rounded-full ${meta.dot} ${meta.pulse ? "animate-pulse-dot" : ""}`} />
                      {meta.label}
                    </span>
                  </div>
                  <div className="mt-4">
                    <HealthTimeline buckets={timelines[c.key]} />
                    <div className="mt-1.5 flex items-center justify-between text-xs text-slate-500">
                      <span>{WINDOW_DAYS} days ago</span>
                      <span className="text-slate-400">{uptimeLabel(up.pct)}</span>
                      <span>Today</span>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </section>

        {/* Incident history */}
        <section className="mx-auto max-w-4xl px-5 pb-10 sm:px-6">
          <h2 className="section-label mb-3">Incident history</h2>
          <IncidentList open={incidents.open} resolved={incidents.resolved} />
        </section>

        {/* Note */}
        <section className="mx-auto max-w-4xl px-5 pb-24 sm:px-6">
          <div className="card border-dashed">
            <p className="text-sm leading-relaxed text-slate-400">
              <span className="font-medium text-slate-200">About this page.</span> Component
              states above are checked live against the Nxeon platform and refresh roughly every 15
              seconds. Uptime percentages and the history strips are computed from real periodic
              health snapshots — where a component has no history yet, we say so rather than assume
              it was up. For an active incident affecting your service, or help with your own server,
              open a ticket from your{" "}
              <a href="/dashboard" className="text-brand-300 hover:text-brand-200">
                dashboard
              </a>
              .
            </p>
          </div>
        </section>
      </main>
      <MarketingFooter />
    </div>
  );
}

