 * case here is deterministic and DB-free.
 *
 * The honesty invariant is the point: uptime must be computed from real samples,
 * and a window with NO samples must read `null` ("collecting data") — never a
 * fabricated 100%.
 */

const MIN = 60_000;
const HOUR = 60 * MIN;
const NOW = Date.parse("2026-07-27T12:00:00.000Z");

function at(msAgo: number): Date {
  return new Date(NOW - msAgo);
}

/* -------------------------- uptimeFromSamples -------------------------- */

test("no samples in window ⇒ pct is null, not 100 (collecting data)", () => {
  const r = uptimeFromSamples([], NOW, 24 * HOUR);
  assert.equal(r.pct, null);
  assert.equal(r.total, 0);
  assert.equal(r.up, 0);
});

test("all-operational ⇒ 100% and every sample counted up", () => {
  const s: SampleLite[] = [at(1 * HOUR), at(2 * HOUR), at(3 * HOUR)].map((ts) => ({
    status: "operational",
    ts,
  }));
  const r = uptimeFromSamples(s, NOW, 24 * HOUR);
  assert.equal(r.pct, 100);
  assert.equal(r.total, 3);
  assert.equal(r.up, 3);
});

test("only operational counts as up — degraded and down are both downtime", () => {
  const s: SampleLite[] = [
    { status: "operational", ts: at(1 * HOUR) },
    { status: "operational", ts: at(2 * HOUR) },
    { status: "degraded", ts: at(3 * HOUR) },
    { status: "down", ts: at(4 * HOUR) },
  ];
  const r = uptimeFromSamples(s, NOW, 24 * HOUR);
  assert.equal(r.total, 4);
  assert.equal(r.up, 2);
  assert.equal(r.degraded, 1);
  assert.equal(r.down, 1);
  assert.equal(r.pct, 50);
});

test("samples older than the window are excluded", () => {
  const s: SampleLite[] = [
    { status: "operational", ts: at(1 * HOUR) }, // in window
    { status: "down", ts: at(48 * HOUR) }, // outside a 24h window
  ];
  const r = uptimeFromSamples(s, NOW, 24 * HOUR);
  assert.equal(r.total, 1);
  assert.equal(r.pct, 100);
});

test("samples stamped in the future are excluded (clock skew guard)", () => {
  const s: SampleLite[] = [
    { status: "operational", ts: new Date(NOW + HOUR) },
    { status: "operational", ts: at(1 * HOUR) },
  ];
  const r = uptimeFromSamples(s, NOW, 24 * HOUR);
  assert.equal(r.total, 1);
});

test("accepts Date, ISO string and epoch-ms timestamps alike", () => {
  const s: SampleLite[] = [
    { status: "operational", ts: at(1 * HOUR) },
    { status: "operational", ts: new Date(NOW - 2 * HOUR).toISOString() },
    { status: "down", ts: NOW - 3 * HOUR },
  ];
  const r = uptimeFromSamples(s, NOW, 24 * HOUR);
  assert.equal(r.total, 3);
  assert.equal(r.up, 2);
});

/* ---------------------------- bucketTimeline --------------------------- */

test("timeline produces exactly bucketCount buckets", () => {
  const b = bucketTimeline([], NOW, 24 * HOUR, 24);
  assert.equal(b.length, 24);
});

test("empty buckets stay null (rendered as 'no data', never green)", () => {
  const b = bucketTimeline([], NOW, 24 * HOUR, 24);
  assert.ok(b.every((x) => x.status === null && x.total === 0));
});

test("a bucket reduces to its WORST status", () => {
  // Window = 4h, 4 buckets of 1h each. Put two readings in the most-recent bucket:
  // one operational, one degraded ⇒ the bucket must be degraded.
  const s: SampleLite[] = [
    { status: "operational", ts: at(10 * MIN) },
    { status: "degraded", ts: at(20 * MIN) },
  ];
  const b = bucketTimeline(s, NOW, 4 * HOUR, 4);
  assert.equal(b[3].total, 2);
  assert.equal(b[3].status, "degraded");
  // A single `down` anywhere in a bucket wins over everything else.
  const s2: SampleLite[] = [
    { status: "operational", ts: at(10 * MIN) },
    { status: "down", ts: at(15 * MIN) },
    { status: "degraded", ts: at(20 * MIN) },
  ];
  assert.equal(bucketTimeline(s2, NOW, 4 * HOUR, 4)[3].status, "down");
});

test("samples land in the correct bucket by time", () => {
  const s: SampleLite[] = [{ status: "down", ts: at(3.5 * HOUR) }];
  const b = bucketTimeline(s, NOW, 4 * HOUR, 4);
  // 3.5h ago in a 4h/4-bucket window ⇒ the oldest bucket (index 0).
  assert.equal(b[0].status, "down");
  assert.ok(b.slice(1).every((x) => x.status === null));
});

/* ----------------------------- worstStatus ---------------------------- */

test("worstStatus ranks down > degraded > operational", () => {
  assert.equal(worstStatus(["operational", "operational"]), "operational");
  assert.equal(worstStatus(["operational", "degraded"]), "degraded");
  assert.equal(worstStatus(["degraded", "down", "operational"]), "down");
  assert.equal(worstStatus([]), "operational");
});

import { test } from "node:test";
import assert from "node:assert/strict";
import {
  decideIncident,
  autoIncidentCopy,
  INCIDENT_OPEN_STREAK,
  INCIDENT_RESOLVE_STREAK,
  type CompStatus,
} from "../lib/monitoring.ts";
import { COMPONENT_LABELS } from "../lib/status-copy.ts";

/**
 * The auto-incident state machine (pure, DB-free). `decideIncident` is called
 * once per component per sweep; these cases pin down exactly when it opens and
 * closes an incident, using the configured streak thresholds so the suite tracks
 * the real config rather than a hard-coded 3/2.
 *
 * `recent` is MOST-RECENT-FIRST (index 0 = newest sample).
 */

const OPEN = INCIDENT_OPEN_STREAK;
const RESOLVE = INCIDENT_RESOLVE_STREAK;

function repeat(status: CompStatus, n: number): CompStatus[] {
  return Array.from({ length: n }, () => status);
}

test("streak thresholds are sane (>=1) so the machine can ever fire", () => {
  assert.ok(OPEN >= 1);
  assert.ok(RESOLVE >= 1);
});

/* ------------------------------- opening ------------------------------ */

test("does NOT open before the unhealthy streak is reached", () => {
  const recent = [...repeat("down", OPEN - 1), "operational" as CompStatus];
  assert.deepEqual(decideIncident(recent, false), { action: "none" });
});

test("opens a DOWN incident once the streak of downs is reached", () => {
  const recent = repeat("down", OPEN);
  assert.deepEqual(decideIncident(recent, false), { action: "open", severity: "down" });
});

test("opens a DEGRADED incident when the newest sample is degraded", () => {
  // Enough consecutive unhealthy samples, but the newest is degraded, not down.
  const recent: CompStatus[] = ["degraded", ...repeat("down", OPEN - 1)];
  assert.deepEqual(decideIncident(recent, false), { action: "open", severity: "degraded" });
});

test("only the LEADING run counts — an old outage with a fresh recovery does not open", () => {
  // Newest is operational, so the leading unhealthy streak is 0 even though the
  // history is full of downs.
  const recent: CompStatus[] = ["operational", ...repeat("down", OPEN + 3)];
  assert.deepEqual(decideIncident(recent, false), { action: "none" });
});

test("a recovery in the middle breaks the streak", () => {
  // [down, operational, down, down, …] — leading unhealthy run is just 1.
  const recent: CompStatus[] = ["down", "operational", ...repeat("down", OPEN)];
  assert.deepEqual(decideIncident(recent, false), { action: "none" });
});

test("does not re-open when an incident is already open (idempotent)", () => {
  const recent = repeat("down", OPEN);
  assert.deepEqual(decideIncident(recent, true), { action: "none" });
});

/* ------------------------------ resolving ----------------------------- */

test("resolves an open incident after the healthy streak is reached", () => {
  const recent = repeat("operational", RESOLVE);
  assert.deepEqual(decideIncident(recent, true), { action: "resolve" });
});

test("does NOT resolve before the healthy streak is reached", () => {
  const recent: CompStatus[] = [...repeat("operational", RESOLVE - 1), "down"];
  // If RESOLVE is 1 this array has a single leading operational and resolves; guard.
  if (RESOLVE > 1) {
    assert.deepEqual(decideIncident(recent, true), { action: "none" });
  }
});

test("a still-unhealthy component keeps the incident open", () => {
  assert.deepEqual(decideIncident(["down", "down"], true), { action: "none" });
});

test("no resolve is emitted when there is nothing open", () => {
  const recent = repeat("operational", RESOLVE + 2);
  assert.deepEqual(decideIncident(recent, false), { action: "none" });
});

test("empty history is a no-op in both states", () => {
  assert.deepEqual(decideIncident([], false), { action: "none" });
  assert.deepEqual(decideIncident([], true), { action: "none" });
});

/* --------------------------- auto copy safety ------------------------- */

test("auto-incident copy is public-safe: names the friendly component, no raw detail", () => {
  const c = autoIncidentCopy("proxmox", "down");
  assert.ok(c.title.includes(COMPONENT_LABELS.proxmox));
  assert.ok(c.body.length > 0);
  // Must NOT contain internal probe wording that the raw `detail` strings carry.
  const blob = `${c.title} ${c.body}`.toLowerCase();
  for (const leak of ["proxmox", "127.0.0.1", "select 1", "queued", "econn", "token", "node "]) {
    assert.ok(!blob.includes(leak), `auto copy leaked internal token: ${leak}`);
  }
});

test("degraded severity yields degraded wording, down yields disruption wording", () => {
  assert.match(autoIncidentCopy("worker", "degraded").body, /degraded/i);
  assert.match(autoIncidentCopy("worker", "down").body, /disruption/i);
});

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { stripComments, stripCommentsAndStrings } from "./_source-tools.ts";

/**
 * Structural tripwires for the health/status layer — the guarantees that a unit
 * test over pure functions can't see:
 *
 *  1. sampleHealth() actually persists HealthSample rows and drives incidents.
 *  2. Every "use server" export in actions-status.ts re-checks requireArea("fleet"),
 *     because "use server" makes each one a public endpoint.
 *  3. The public /api/health route still SANITIZES (never leaks raw detail).
 *  4. The public /status page never renders a component's internal `detail`.
 *  5. The exports the MarketingFooter and admin page depend on still exist.
 */

const ROOT = join(import.meta.dirname, "..");
const read = (p: string) => readFileSync(join(ROOT, p), "utf8");
const shape = (p: string) => stripCommentsAndStrings(read(p));
const literal = (p: string) => stripComments(read(p));

/* ------------------- 1. sampleHealth writes history ------------------- */

test("sampleHealth persists a HealthSample per component and manages incidents", () => {
  const src = shape("lib/monitoring.ts");
  assert.match(src, /export async function sampleHealth/);
  assert.match(src, /healthSample\.createMany/, "sampleHealth must write HealthSample rows");
  assert.match(src, /statusIncident\.create/, "must be able to auto-OPEN an incident");
  assert.match(src, /statusIncident\.update/, "must be able to auto-RESOLVE (stamp resolvedAt)");
  assert.match(src, /resolvedAt/, "resolve path stamps resolvedAt");
  // The auto-incident rows must be flagged auto so manual actions never fight them.
  assert.match(src, /auto:\s*true/);
  // Retention prune keeps the table bounded.
  assert.match(src, /healthSample\.deleteMany/);
});

test("uptime is computed from samples, not fabricated (null path exists)", () => {
  const src = shape("lib/monitoring.ts");
  // The honesty invariant lives in uptimeFromSamples: total 0 ⇒ pct null.
  assert.match(src, /export function uptimeFromSamples/);
  assert.match(src, /total\s*===\s*0\s*\?\s*null/);
});

/* --------------- 2. actions-status is admin-gated per export ----------- */

test("every server action in actions-status.ts calls requireArea inside itself", () => {
  const src = shape("lib/actions-status.ts");
  assert.match(src, /["']use server["']/, "file must be a server-action module");

  const parts = src.split(/export async function/).slice(1);
  assert.ok(parts.length >= 2, "expected multiple exported server actions");
  for (const part of parts) {
    const name = part.trim().split(/[(\s]/)[0];
    assert.match(part, /requireArea\(/, `export ${name} must call requireArea() itself`);
  }
});

test("the gated area is the fleet (admin) area, not a weaker one", () => {
  const src = literal("lib/actions-status.ts");
  // Count matches on the real literal (stripComments keeps string values).
  const gate = src.match(/requireArea\("fleet"\)/g) ?? [];
  const exports = src.match(/export async function/g) ?? [];
  assert.equal(gate.length, exports.length, "one requireArea(\"fleet\") per exported action");
});

/* ------------------ 3. /api/health still sanitizes -------------------- */

test("/api/health sanitizes and never returns raw getHealth detail", () => {
  const src = shape("app/api/health/route.ts");
  assert.match(src, /function sanitize/);
  assert.match(src, /PUBLIC_DETAIL/);
  // The response body must be the sanitized shape, not the raw report.
  assert.match(src, /NextResponse\.json\(\s*sanitize\(/);
  // Guard: it must NOT json the raw cache body / report directly.
  assert.doesNotMatch(src, /NextResponse\.json\(\s*cache\.body/);
});

/* --------------- 4. public /status never renders `.detail` ------------ */

test("public status page never reads a component's internal detail", () => {
  const src = shape("app/status/page.tsx");
  assert.doesNotMatch(src, /\.detail\b/, "the /status page must not surface probe detail");
});

test("public status client components do not import the DB-bound monitoring module for values", () => {
  // Timeline / incident list are client components; they must be fed serialisable
  // props, not import runtime helpers out of lib/monitoring.
  for (const f of ["components/status/HealthTimeline.tsx", "components/status/IncidentList.tsx"]) {
    const src = shape(f);
    assert.doesNotMatch(
      src,
      /import\s+\{[^}]*\}\s+from\s+["'][^"']*lib\/monitoring["']/,
      `${f} must not value-import lib/monitoring`
    );
  }
});

/* --------------- 5. back-compat: existing consumers intact ------------ */

test("lib/monitoring.ts still exports everything MarketingFooter + admin page need", () => {
  const src = shape("lib/monitoring.ts");
  for (const sym of [
    "getHealth",
    "overallStatus",
    "workerHealth",
    "stuckJobs",
    "nodeStorageUsage",
    "nodeRamUsage",
    "backupSummary",
    "fmtAge",
    "DISK_WARN_RATIO",
    "RAM_WARN_RATIO",
    "BACKUP_STALE_MS",
  ]) {
    assert.match(src, new RegExp(`export (async function|function|const) ${sym}\\b`), `missing export ${sym}`);
  }
  // CompStatus is the type the footer + page import.
  assert.match(src, /export type CompStatus/);
});

test("status-copy still exports the footer's OVERALL_TITLE + STATUS_DOT", () => {
  const src = shape("lib/status-copy.ts");
  assert.match(src, /export const OVERALL_TITLE/);
  assert.match(src, /export const STATUS_DOT/);
});

